const rooms = new Map([["R1", "Deluxe"]]);
const bookings = [
  { id: "B1", roomId: "R1" },
  { id: "B2", roomId: "R9" },
];

function roomFor(bookingId: string): string {
  const booking = bookings.find((b) => b.id === bookingId);
  if (booking === undefined) throw new Error("booking not found");
  return rooms.get(booking.roomId) ?? "room unavailable";
}

console.log(roomFor("B1"));
console.log(roomFor("B2"));
try {
  roomFor("B7");
} catch (error) {
