interface NewUser {
  email: string;
  name: string;
}

function parseNewUser(body: unknown): NewUser | null {
  if (typeof body !== "object" || body === null) return null;
  if (!("email" in body) || typeof body.email !== "string") return null;
  if (!("name" in body) || typeof body.name !== "string") return null;
  return { email: body.email, name: body.name };
}

console.log(parseNewUser({ email: "eve@example.com", name: "Eve", role: "admin" }));
console.log(parseNewUser({ name: "Tunde" }));
console.log(parseNewUser("hello"));

