function total(amounts: (number | string)[]): number {
  let sum = 0;
  for (const amount of amounts) {
    const value = typeof amount === "string" ? Number(amount) : amount;
    if (Number.isFinite(value)) sum += value;
  }
  return sum;
}

console.log(total([1000, "500", "abc", 250]));

